public interface ISqsHandler
{
    Task HandleAsync(string body, CancellationToken ct);
}

public sealed class HandlerRegistry(IReadOnlyDictionary<string, ISqsHandler> handlers)
{
    public Task DispatchAsync(string type, string body, CancellationToken ct) =>
        handlers.TryGetValue(type, out var handler)
            ? handler.HandleAsync(body, ct)
            : throw new InvalidOperationException(type);
}

